// Standalone integration suite. Only synthetic data and loopback network.
using System;
using System.IO;
using System.IO.Compression;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Net;
using IptvWindows;

class CoreTests {
 static string Base, Output, Work;
 static readonly List<object> Results=new List<object>();
 static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Equal<T>(T expected,T actual,string message){if(!Object.Equals(expected,actual))throw new Exception(message+"; expected="+expected+"; actual="+actual);}
 static void Check(string name,Action test){try{test();Results.Add(new {name=name,status="passed"});Console.WriteLine("PASS "+name);}catch(Exception e){Results.Add(new {name=name,status="failed",error=e.GetType().Name+": "+e.Message});Console.WriteLine("FAIL "+name+": "+e.Message);}}
 static void Throws<T>(Action test,string message) where T:Exception{try{test();}catch(T){return;}throw new Exception(message);}
 static Profile Xtream(string segment,string category){return new Profile{Type="xtream",Address=Base+segment,Username="fixture user+ю",Password="fixture&pass=1",Category=category};}
 static Provider NewProvider(){return new Provider(new Settings{UserAgent="CoreTests/fixture"});}
 static string Stamp(DateTimeOffset t){return t.ToString("yyyyMMddHHmmss zzz").Replace(":","");}
 static byte[] Guide(DateTimeOffset now){return Encoding.UTF8.GetBytes("<?xml version=\"1.0\" encoding=\"utf-8\"?><tv>"+
  "<programme channel=\"Bg.One\" start=\""+Stamp(now.AddMinutes(-10).ToOffset(TimeSpan.FromHours(3)))+"\" stop=\""+Stamp(now.AddMinutes(10).ToOffset(TimeSpan.FromHours(3)))+"\"><title>Сега</title><desc>Текущо предаване</desc></programme>"+
  "<programme channel=\"Bg.One\" start=\""+Stamp(now.AddMinutes(10).ToOffset(TimeSpan.FromHours(-5.5)))+"\" stop=\""+Stamp(now.AddMinutes(40).ToOffset(TimeSpan.FromHours(-5.5)))+"\"><title>Следва</title><desc>Следващо предаване</desc></programme>"+
  "</tv>");}
 static void Main(string[] args){
  Base=args[0];Output=args[1];Work=args[2];Directory.CreateDirectory(Work);
  Check("m3u_url_bom_quoted_commas_cyrillic_headers_epg",delegate{
   var p=new Profile{Type="m3u",Address=Base+"/lists/basic.m3u"};var list=NewProvider().Load(p).GetAwaiter().GetResult();
   Equal(2,list.Count,"channel count");Equal("Новини, 24 часа",list[0].Name,"title commas");Equal("Новини, България",list[0].Group,"quoted group commas");Equal("bg.one",list[0].TvgId,"EPG ID");Equal("logo,one.png",list[0].Logo,"logo attr");Equal(Base+"/lists/streams/one.m3u8",list[0].Url,"relative child URL");
   Equal("Fixture channel agent",list[0].UserAgent,"VLC user agent");Equal("http://127.0.0.1/reference",list[0].Referer,"VLC referrer");Equal("Encoded Agent",list[1].UserAgent,"inline encoded agent");Equal("http://127.0.0.1/ref",list[1].Referer,"inline encoded referer");Equal("http://127.0.0.1/epg-fixture.xml",p.Epg,"header epg");
  });
  Check("m3u_root_relative_url",delegate{var c=Playlist.Parse("#EXTM3U\n#EXTINF:-1,Root\n/stream/one.ts\n",Base+"/lists/a.m3u").Single();Equal(Base+"/stream/one.ts",c.Url,"root-relative URLs must retain HTTP origin");});
  Check("m3u_scheme_relative_url",delegate{var c=Playlist.Parse("#EXTINF:-1,Scheme\n//127.0.0.1:7777/stream.ts\n",Base+"/a.m3u").Single();Equal("http://127.0.0.1:7777/stream.ts",c.Url,"scheme-relative URLs must retain HTTP scheme");});
  Check("m3u_single_quotes_extgrp_bare_url_and_invalid_scheme",delegate{var c=Playlist.Parse("#EXTM3U\n#EXTGRP:Група\n#EXTINF:-1 tvg-id='x,y' group-title='Друга, група',Име\nhttp://127.0.0.1/a\nhttp://127.0.0.1/b\n#EXTINF:-1,Invalid\njavascript:bad\n","");Equal(2,c.Count,"unsupported scheme excluded");Equal("x,y",c[0].TvgId,"single quoted tvg-id");Equal("Друга, група",c[0].Group,"single quoted group");Equal("Група",c[1].Group,"EXTGRP inherited by bare URL");});
  Check("m3u_local_relative_path",delegate{var list=Playlist.Parse("#EXTINF:-1,Локален\nsub/one.ts\n",Path.Combine(Work,"local.m3u"));Equal(new Uri(Path.Combine(Work,"sub","one.ts")).AbsoluteUri,list.Single().Url,"local relative URI");});
  Check("m3u_export_roundtrip_retains_metadata_and_headers",delegate{var input=new Channel{Name="Име, запетая",Url=Base+"/stream.ts",Group="Група",Logo=Base+"/logo.png",TvgId="bg.one",UserAgent="Agent",Referer=Base+"/referer"};var output=Playlist.Parse(Playlist.Export(new[]{input}),"").Single();Equal(input.Name,output.Name,"name");Equal(input.Group,output.Group,"group");Equal(input.TvgId,output.TvgId,"epg id");Equal(input.Logo,output.Logo,"logo must survive export");Equal(input.UserAgent,output.UserAgent,"agent");Equal(input.Referer,output.Referer,"referrer");Equal(input.Url,output.Url,"URL");});
  Check("network_gzip_and_response_limit",delegate{Equal("Кирилица gzip",Net.Text(Base+"/gzip-text","CoreTests/fixture",null).GetAwaiter().GetResult(),"automatic HTTP gzip");Throws<InvalidDataException>(delegate{Net.Bytes(Base+"/oversize","CoreTests/fixture",null,1024).GetAwaiter().GetResult();},"max response size must reject oversized response");});
  Check("xtream_live_credentials_categories_default_extension_epg",delegate{var p=Xtream("/xtream","live");var c=NewProvider().Load(p).GetAwaiter().GetResult().Single();Equal("live",c.Kind,"kind");Equal("Телевизия едно",c.Name,"unicode name");Equal("Български live",c.Group,"category join");Equal("bg.one",c.TvgId,"EPG join");Assert(c.Url.EndsWith("/101.ts"),"live default extension");Assert(c.Url.Contains(Uri.EscapeDataString(p.Username)),"URL username escaped");Assert(c.Url.Contains(Uri.EscapeDataString(p.Password)),"URL password escaped");Assert(p.Epg.StartsWith(Base+"/xtream/xmltv.php?"),"EPG auto URL");});
  Check("xtream_vod_and_series_episode_expansion",delegate{var provider=NewProvider();var vod=provider.Load(Xtream("/xtream","vod")).GetAwaiter().GetResult().Single();Equal("vod",vod.Kind,"vod kind");Assert(vod.Url.Contains("/movie/")&&vod.Url.EndsWith("/202.mkv"),"vod path/container");var p=Xtream("/xtream","series");var series=provider.Load(p).GetAwaiter().GetResult().Single();Equal("series:303",series.Url,"series placeholder");var ep=provider.Episodes(p,series).GetAwaiter().GetResult();Equal(2,ep.Count,"episode count");Equal("Първи епизод",ep[0].Name,"season 1 first");Equal("Сезон 1",ep[0].Group,"season group");Assert(ep[0].Url.Contains("/series/")&&ep[0].Url.EndsWith("/301.mp4"),"episode default extension");Assert(ep[1].Url.EndsWith("/302.mkv"),"episode explicit extension");});
  foreach(string rejection in new[]{"auth","expired","disabled","missing"}){string value=rejection;Check("xtream_reject_"+value,delegate{Throws<IOException>(delegate{NewProvider().Load(Xtream("/reject-"+value,"live")).GetAwaiter().GetResult();},"invalid account must reject");});}
  Check("stalker_handshake_headers_pagination_dedup_create_link",delegate{var provider=NewProvider();var p=new Profile{Type="portal",Address=Base+"/stalkerA/c",Mac="00:1a:79:00:00:01"};var list=provider.Load(p).GetAwaiter().GetResult();Equal(3,list.Count,"two pages with duplicate must yield 3 channels");Equal("Новини",list[0].Group,"genre join");Equal("bg.1",list[0].TvgId,"XMLTV ID");Equal("portal",list[0].Kind,"portal kind");Equal(Base+"/resolved/stalkerA/stream.ts",provider.Resolve(p,list[0]).GetAwaiter().GetResult(),"create_link and ffmpeg stripping");var requests=Net.Text(Base+"/requests","CoreTests/fixture",null).GetAwaiter().GetResult();Assert(requests.Contains("get_profile")&&requests.Contains("get_genres")&&requests.Contains("create_link"),"expected protocol phases recorded");});
  Check("stalker_resolve_remains_bound_to_correct_profile",delegate{var provider=NewProvider();var a=new Profile{Type="portal",Address=Base+"/stalkerA/c",Mac="00:1a:79:00:00:01"};var b=new Profile{Type="portal",Address=Base+"/stalkerB/c",Mac="00:1a:79:00:00:02"};var ca=provider.Load(a).GetAwaiter().GetResult()[0];provider.Load(b).GetAwaiter().GetResult();Equal(Base+"/resolved/stalkerA/stream.ts",provider.Resolve(a,ca).GetAwaiter().GetResult(),"resolving A after loading B must use A session");});
  Check("storage_second_write_backup_and_corrupt_preservation",delegate{var st=new Storage(Path.Combine(Work,"storage"));st.Write("settings.json",new Settings{Volume=10});st.Write("settings.json",new Settings{Volume=20});Equal(20,st.Read("settings.json",new Settings()).Volume,"new settings");var previous=Storage.Json().Deserialize<Settings>(File.ReadAllText(Path.Combine(st.Root,"settings.json.bak")));Equal(10,previous.Volume,"backup is previous write");st.Write("settings.json",new Settings{Volume=30});Equal(20,Storage.Json().Deserialize<Settings>(File.ReadAllText(Path.Combine(st.Root,"settings.json.bak"))).Volume,"backup updated after third write");string path=Path.Combine(st.Root,"settings.json");File.WriteAllText(path,"{broken",Encoding.UTF8);Throws<InvalidDataException>(delegate{st.Read("settings.json",new Settings());},"corrupt settings reject");Equal("{broken",File.ReadAllText(path),"corrupt original unchanged");Assert(File.Exists(path+".bak"),"backup retained");Equal(75,st.Read("absent.json",new Settings()).Volume,"absent settings default");});
  Check("storage_empty_file_rejected_as_corrupt",delegate{var st=new Storage(Path.Combine(Work,"empty"));File.WriteAllText(Path.Combine(st.Root,"settings.json"),"");Throws<InvalidDataException>(delegate{st.Read("settings.json",new Settings());},"empty existing settings must be rejected, not return null");});
  Check("xmltv_current_next_offsets_case_insensitive_gzip",delegate{var now=DateTimeOffset.UtcNow;var bytes=Guide(now);var guide=Epg.Parse(bytes);Equal("Сега",guide.Now("bg.one",now).Title,"current by normalized ID");Equal("Текущо предаване",guide.Now("BG.ONE",now).Description,"description");Equal("Следва",guide.Next("bg.one",now).Title,"next with negative offset");Equal(TimeSpan.FromHours(3),guide.Now("bg.one",now).Start.Offset,"positive zone preserved");Equal(TimeSpan.FromHours(-5.5),guide.Next("bg.one",now).Start.Offset,"negative zone preserved");Assert(guide.Now("missing",now)==null,"unknown channel");byte[] packed;using(var ms=new MemoryStream()){using(var gz=new GZipStream(ms,CompressionMode.Compress,true)){gz.Write(bytes,0,bytes.Length);}packed=ms.ToArray();}Equal("Следва",Epg.Parse(packed).Next("bg.one",now).Title,"gzip XMLTV");});
  string serialized=Storage.Json().Serialize(Results);int failed=System.Text.RegularExpressions.Regex.Matches(serialized,"\"status\":\"failed\"").Count;
  File.WriteAllText(Output,Storage.Json().Serialize(new{suite="Core integration",executedAt=DateTimeOffset.UtcNow.ToString("o"),networkBoundary="127.0.0.1 only; synthetic credentials and media",coreSha256=Hash(args[3]),total=Results.Count,passed=Results.Count-failed,failed=failed,results=Results}),new UTF8Encoding(false));
  Console.WriteLine("RESULT "+(Results.Count-failed)+"/"+Results.Count+" passed");Environment.ExitCode=failed==0?0:1;
 }
 static string Hash(string path){using(var s=File.OpenRead(path))using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
}
